[CmdletBinding()]
param()
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot '..\scan.ps1')
$passed = 0; $failed = 0
function Assert-Equal($actual, $expected, $name) { if ($actual -ne $expected) { throw "$name (actual=$actual expected=$expected)" } }
function Assert-True($condition, $name) { if (!$condition) { throw $name } }
function Test-Case($name, [scriptblock]$block) { try { & $block; Write-Host "PASS: $name" -ForegroundColor Green; $script:passed++ } catch { Write-Host "FAIL: $name - $($_.Exception.Message)" -ForegroundColor Red; $script:failed++ } }
Test-Case 'Battery wear calculation' { Assert-Equal (Get-BatteryWear 50000 40000) 20 'wear' }
Test-Case 'Battery data unavailable' { $x = Get-BatterySection; Assert-True ($null -ne $x) 'section exists' }
Test-Case 'PnP code 0 is OK' { Assert-Equal (Get-PnpClassification 0).Status 'OK' 'status' }
Test-Case 'PnP code 22 is WARNING' { Assert-Equal (Get-PnpClassification 22).Status 'WARNING' 'status'; Assert-True ((Get-PnpClassification 22).Interpretation -match 'disabled') 'interpretation' }
Test-Case 'PnP code 24 is WARNING' { Assert-Equal (Get-PnpClassification 24).Status 'WARNING' 'status'; Assert-True ((Get-PnpClassification 24).Interpretation -match 'further inspection') 'interpretation' }
Test-Case 'Unknown PnP code is conservative' { Assert-Equal (Get-PnpClassification 999).Status 'WARNING' 'status'; Assert-True ((Get-PnpClassification 999).Interpretation -notmatch 'physical failure confirmed') 'interpretation' }
Test-Case 'Missing PnP data is N/A' { Assert-Equal (Get-PnpClassification $null).Status 'N/A' 'status' }
Test-Case 'Desktop without battery is not error' { $r=[pscustomobject]@{ PnpProblems=@(); ModuleErrors=@(); Battery=[pscustomobject]@{ WearPercent='N/A' } }; Assert-Equal (Get-OverallStatus $r) 'OK' 'overall' }
Test-Case 'PnP warning aggregates to WARNING' { $r=[pscustomobject]@{ PnpProblems=@([pscustomobject]@{Status='WARNING'}); ModuleErrors=@(); Battery=[pscustomobject]@{ WearPercent='N/A' } }; Assert-Equal (Get-OverallStatus $r) 'WARNING' 'overall' }
Test-Case 'ASCII-safe banner' { $r=[pscustomobject]@{ Generated=(Get-Date); OverallStatus='OK'; Computer=[pscustomobject]@{ Hostname='TESTPC'; SerialNumber='x' }; CPU=@(); Memory=@(); Disks=@(); Battery=@(); GPU=@(); Network=@(); PnpProblems=@(); ModuleErrors=@() }; Assert-True ((Convert-ReportToText $r) -match '^CK Hardware Scanner \| Inspection Report') 'banner' }
Test-Case 'Storage health unavailable is N/A' { $x = Get-DiskSection; Assert-True ($x.Count -ge 0) 'section returned' }
Test-Case 'PnP problem model preserves code' { $x = [pscustomobject]@{ Name='Mock device'; ConfigManagerErrorCode=28 }; Assert-Equal $x.ConfigManagerErrorCode 28 'problem code' }
Test-Case 'Empty results render N/A' { Assert-True ((Format-Section 'Mock' @()) -join "`n" -match 'N/A') 'empty output' }
Test-Case 'Module error is contained' { $x = Invoke-SafeModule 'Mock' { throw 'expected' }; Assert-Equal $x.Module 'Mock' 'module'; Assert-True ($x.Error -match 'expected') 'error' }
Test-Case 'Module error detection handles success object' { $x=Get-ModuleErrorResults ([pscustomobject]@{Name='ok';Value=1}); Assert-Equal @($x).Count 0 'success object' }
Test-Case 'Module error detection handles failure object' { $x=Get-ModuleErrorResults ([pscustomobject]@{Module='Mock';Error='expected'}); Assert-Equal @($x).Count 1 'failure object'; Assert-Equal $x[0].Module 'Mock' 'module' }
Test-Case 'Module error detection handles arrays and null' { $x=Get-ModuleErrorResults @($null,[pscustomobject]@{Name='ok'},[pscustomobject]@{Module='Mock';Error='expected'}); Assert-Equal @($x).Count 1 'array failure' }
Test-Case 'New scan preserves module errors and continues' { $r=New-ScanReport; Assert-True ($null -ne $r.CPU -and $null -ne $r.Memory -and $null -ne $r.ModuleErrors) 'scan continues' }
Test-Case 'Optional sensor errors do not become critical errors' { $r=[pscustomobject]@{PnpProblems=@();ModuleErrors=@();SensorErrors=@([pscustomobject]@{Module='Sensors';Error='optional failure'});Battery=[pscustomobject]@{WearPercent='N/A'}}; Assert-Equal (Get-OverallStatus $r) 'OK' 'sensor status' }
Test-Case 'TXT report creation' { $r = [pscustomobject]@{ Generated=(Get-Date); OverallStatus='OK'; Computer=[pscustomobject]@{ Hostname='TESTPC' }; CPU=@(); Memory=@(); Disks=@(); Battery=@(); GPU=@(); Network=@(); PnpProblems=@(); ModuleErrors=@() }; $p = Write-ReportFile $r (Join-Path $env:TEMP 'ck-hardware-scanner-tests'); Assert-True (Test-Path $p) 'file exists'; Remove-Item -LiteralPath $p -Force }
Test-Case 'JSON report is valid and structured' { $r=New-ScanReport; $j=Convert-ReportToJson $r | ConvertFrom-Json; Assert-Equal $j.Title 'CK Hardware Scanner | Inspection Report' 'title'; Assert-True ($null -ne $j.Hardware) 'hardware' }
Test-Case 'HTML report has print control and escaped data' { $r=[pscustomobject]@{ Generated=(Get-Date); OverallStatus='OK'; Computer=[pscustomobject]@{ Hostname='<PC>'; Model='M&1'; SerialNumber='S' }; CPU=[pscustomobject]@{ Name='CPU' }; Memory=[pscustomobject]@{ TotalGB=1; UsedPercent=2 }; Disks=@(); Battery=[pscustomobject]@{ Available=$false; WearPercent='N/A' }; GPU=@(); Network=@(); PnpProblems=@(); ModuleErrors=@() }; $h=Convert-ReportToHtml $r; Assert-True ($h -match 'window.print') 'print'; Assert-True ($h -match '&lt;PC&gt;') 'escaped' }
Test-Case 'Masking removes sensitive export values' { $r=[pscustomobject]@{ Generated=(Get-Date); OverallStatus='OK'; Computer=[pscustomobject]@{ Hostname='PC'; Model='M'; SerialNumber='SECRET-SERIAL' }; CPU=@(); Memory=@(); Disks=@(); Battery=[pscustomobject]@{ Available=$false; WearPercent='N/A' }; GPU=@(); Network=@([pscustomobject]@{ Name='NIC'; MAC='SECRET-MAC'; Speed=1 }); PnpProblems=@(); ModuleErrors=@() }; $x=Get-ExportReport $r -RedactSensitive; $s=$x | ConvertTo-Json -Depth 8; Assert-True ($s -notmatch 'SECRET-SERIAL|SECRET-MAC') 'masked' }
Test-Case 'HTML output file uses requested extension' { $r=New-ScanReport; $d=Join-Path $env:TEMP 'ck-hardware-scanner-phase2'; $p=Write-ReportFile $r $d 'HTML'; Assert-True ($p -match '\.html$' -and (Test-Path $p)) 'html path'; Remove-Item -LiteralPath $p -Force }
Test-Case 'RAM fixture maps all available fields' { $m=[pscustomobject]@{DeviceLocator='DIMM_A1';BankLabel='BANK 0';Capacity=8589934592;Manufacturer='Acme';PartNumber='P1';SerialNumber='RAMSECRET';SMBIOSMemoryType=26;MemoryType=24;Speed=1600;ConfiguredClockSpeed=1600;ConfiguredVoltage=1350;FormFactor=8;Rank=2;TotalWidth=72;DataWidth=64}; $x=Convert-MemoryModule $m; Assert-Equal $x.Slot.Value 'DIMM_A1' 'slot'; Assert-Equal $x.MemoryType 'DDR4' 'type'; Assert-Equal $x.SMBIOSMemoryType 26 'raw'; Assert-Equal $x.SpeedMHz.Value 1600 'speed'; Assert-Equal $x.ConfiguredClockSpeedMHz.Value 1600 'configured'; Assert-Equal $x.Voltage.Value '1350 mV' 'voltage' }
Test-Case 'Unknown SMBIOS type is not guessed' { $x=Get-MemoryTypeName 99 0; Assert-Equal $x.Name 'Unknown' 'type'; Assert-Equal $x.Raw 99 'raw' }
Test-Case 'RAM rated speed remains unavailable' { $m=[pscustomobject]@{SMBIOSMemoryType=24;Speed=1600}; $x=Convert-MemoryModule $m; Assert-Equal $x.RatedSpeedMHz.Value 'N/A' 'rated' }
Test-Case 'Multiple RAM modules remain separate' { $r=[pscustomobject]@{Memory=[pscustomobject]@{TotalGB=16;UsedPercent=20;Modules=@((Convert-MemoryModule ([pscustomobject]@{DeviceLocator='A';Capacity=1})),(Convert-MemoryModule ([pscustomobject]@{DeviceLocator='B';Capacity=2})))}; CPU=[pscustomobject]@{Name='CPU';Cores=1;LogicalProcessors=1;MaxClockMHz=1}; Disks=@(); Battery=[pscustomobject]@{Available=$false;WearPercent='N/A'}; GPU=@()}; Assert-Equal @((Get-HardwareRows $r | Where-Object {$_.Component -like 'RAM *'})).Count 2 'module rows' }
Test-Case 'RAM serial remains visible for internal diagnosis' { $m=Convert-MemoryModule ([pscustomobject]@{DeviceLocator='A';Capacity=1;SerialNumber='RAMSECRET'}); $r=[pscustomobject]@{Generated=(Get-Date);OverallStatus='OK';Computer=[pscustomobject]@{Hostname='P';Model='M';SerialNumber='SYSSECRET'};CPU=[pscustomobject]@{Name='C';Cores=1;LogicalProcessors=1;MaxClockMHz=1};Memory=[pscustomobject]@{TotalGB=1;UsedPercent=1;Modules=@($m)};Disks=@();Battery=[pscustomobject]@{Available=$false;WearPercent='N/A'};GPU=@();Network=@();PnpProblems=@();ModuleErrors=@()}; $s=(Convert-ReportToText $r)+(Convert-ReportToHtml $r)+(Convert-ReportToJson $r); Assert-True ($s -match 'RAMSECRET') 'serial retained' }
Test-Case 'CPU core and thread fields are distinct' { $r=New-ScanReport; Assert-True ($null -ne $r.CPU.Cores -and $null -ne $r.CPU.Threads) 'core/thread'; Assert-True ((Convert-ReportToText $r) -match 'Threads') 'label' }
Test-Case 'CPU unavailable fields remain N/A' { $x=Get-PropertyValue ([pscustomobject]@{}) 'L3CacheSize' 'N/A'; Assert-Equal $x 'N/A' 'cache' }
Test-Case 'System detail contains BIOS Windows and motherboard objects' { $r=New-ScanReport; Assert-True ($null -ne $r.Computer.BIOSDetail -and $null -ne $r.Computer.WindowsDetail -and $null -ne $r.Computer.Motherboard) 'system detail' }
Test-Case 'JSON contains CPU and System details' { $j=Convert-ReportToJson (New-ScanReport) | ConvertFrom-Json; Assert-True ($null -ne $j.Details.CPU -and $null -ne $j.Details.System) 'json detail' }
Test-Case 'RAM structured values are formatted, not raw objects' { $t=Convert-ReportToText (New-ScanReport); Assert-True ($t -notmatch '@\{Value=.*Status=') 'raw RAM object'; Assert-True ($t -match 'RAM DIMM') 'ram slot' }
Test-Case 'Architecture mapping known and unknown' { Assert-Equal (Get-CpuArchitectureName 9) 'x64' 'x64'; Assert-Equal (Get-CpuArchitectureName 999) 'Unknown (999)' 'unknown' }
Test-Case 'Windows fields are exported in all formats' { $r=New-ScanReport; $t=Convert-ReportToText $r; $h=Convert-ReportToHtml $r; $j=Convert-ReportToJson $r | ConvertFrom-Json; Assert-True ($t -match 'WINDOWS' -and $h -match 'WINDOWS' -and $null -ne $j.Details.System.WindowsDetail) 'windows output' }
Test-Case 'Detail layout uses ASCII tables' { $t=Convert-ReportToText (New-ScanReport); Assert-True ($t -match '\+[-+]+\+' -and $t -match '\| Cores / Threads\s+\|') 'table layout'; Assert-True ($t -notmatch '@\{Value=.*Status=') 'no raw object' }
Test-Case 'HTML detail uses table markup' { $h=Convert-ReportToHtml (New-ScanReport); Assert-True ($h -match '<table class="details">' -and $h -match '<th>Property</th>') 'html table' }
Test-Case 'Storage fixture preserves disk identity and volume fields' { $d=[pscustomobject]@{DiskNumber='Disk 7';Model='Mock SSD';Manufacturer='Acme';SerialNumber='DISK-SERIAL';FirmwareRevision='F1';CapacityGB=100;MediaType='SSD';InterfaceType='NVMe';Health='OK';SMART=[pscustomobject]@{Health='Unavailable'};Partitions=@([pscustomobject]@{PartitionNumber=1;DriveLetter='C:';FileSystem='NTFS';SizeGB=100;UsedGB=40;FreeGB=60})}; Assert-Equal $d.DiskNumber 'Disk 7' 'disk number'; Assert-Equal $d.Partitions[0].FreeGB 60 'free space' }
Test-Case 'Battery valid wear and unavailable values are distinct' { Assert-Equal (Get-BatteryWear 100000 75000) 25 'wear'; Assert-Equal (Get-BatteryWear 0 0) $null 'zero design' }
Test-Case 'Windows DateTime values are preserved' { $d=Get-Date; Assert-Equal (Convert-WindowsDate $d) $d 'datetime'; Assert-Equal (Convert-WindowsDate $null) 'N/A' 'missing date' }
Test-Case 'Virtualization fields are separated' { $r=New-ScanReport; Assert-True ($null -ne $r.CPU.VirtualizationCapability -and $null -ne $r.CPU.VirtualizationFirmwareStatus -and $null -ne $r.CPU.HypervisorStatus) 'virtualization fields' }
Test-Case 'Hypervisor makes contradictory processor flags indeterminate' { $m=[pscustomobject]@{VirtualizationFirmwareEnabled=$false;VMMonitorModeExtensions=$false}; $status=if($m.VirtualizationFirmwareEnabled -eq $false){'Unknown (hypervisor present; processor flag is not authoritative)'}else{'x'}; Assert-True ($status -match 'Unknown') 'indeterminate' }
Test-Case 'GPU dedicated and shared memory stay separate' { $r=New-ScanReport; foreach($g in @($r.GPU)){ Assert-True ($g.PSObject.Properties.Name -contains 'DedicatedVRAMGB' -and $g.PSObject.Properties.Name -contains 'SharedMemoryGB') 'gpu memory fields' } }
Test-Case 'Integrated GPU does not claim dedicated VRAM' { $g=[pscustomobject]@{VideoProcessor='Intel Integrated';AdapterRAM=1073741824}; $integrated=($g.VideoProcessor -match 'Intel|UMA|Integrated'); $dedicated=if($integrated){'N/A'}else{'value'}; Assert-Equal $dedicated 'N/A' 'integrated VRAM' }
Test-Case 'Network fields remain distinct' { $r=New-ScanReport; foreach($n in @($r.Network)){ Assert-True ($n.PSObject.Properties.Name -contains 'IPv4' -and $n.PSObject.Properties.Name -contains 'Gateway' -and $n.PSObject.Properties.Name -contains 'DNS') 'network fields' } }
Test-Case 'Sensors are explicit when provider is unavailable' { $s=Get-SensorSnapshot; Assert-Equal $s.ProviderStatus 'Unavailable' 'provider status'; Assert-Equal @($s.Sensors).Count 0 'sensor count' }
Test-Case 'Sensor provider unavailable returns safe snapshot' { $s=Get-SensorSnapshot; Assert-Equal $s.ProviderStatus 'Unavailable' 'provider'; Assert-Equal @($s.Sensors).Count 0 'sensors' }
Test-Case 'Valid sensor snapshot preserves numeric value' { $s=Get-SensorSnapshot { New-SensorRecord 'CPU' 'Package' 42.5 'C' 'Fixture' (Get-Date) }; Assert-Equal $s.Sensors[0].Value 42.5 'value'; Assert-Equal $s.Sensors[0].Status 'Valid' 'status' }
Test-Case 'Duplicate sensors are deterministic' { $s=Get-SensorSnapshot { New-SensorRecord 'CPU' 'Package' 42 'C' 'Fixture' (Get-Date); New-SensorRecord 'CPU' 'Package' 43 'C' 'Fixture' (Get-Date) }; Assert-Equal @($s.Sensors).Count 1 'dedupe' }
Test-Case 'Invalid sensor values are rejected' { $s=Get-SensorSnapshot { New-SensorRecord 'CPU' 'Bad' $null 'C' 'Fixture' (Get-Date); New-SensorRecord 'CPU' 'NaN' ([double]::NaN) 'C' 'Fixture' (Get-Date); New-SensorRecord 'CPU' 'Good' 1 'C' 'Fixture' (Get-Date) }; Assert-Equal @($s.Sensors).Count 1 'valid count' }
Test-Case 'Sensor provider exception is contained' { $s=Get-SensorSnapshot { throw 'sensor failure' }; Assert-Equal $s.ProviderStatus 'Error' 'status'; Assert-True ($s.Errors[0] -match 'sensor failure') 'error' }
Test-Case 'Sensor names and units are required' { $s=Get-SensorSnapshot { New-SensorRecord 'CPU' '' 1 'C' 'Fixture' (Get-Date); New-SensorRecord 'CPU' 'NoUnit' 1 '' 'Fixture' (Get-Date) }; Assert-Equal @($s.Sensors).Count 0 'invalid count' }
Test-Case 'Sensor output is consistent across formats' { $r=New-ScanReport; $t=Convert-ReportToText $r; $h=Convert-ReportToHtml $r; $j=Convert-ReportToJson $r | ConvertFrom-Json; Assert-True ($t -match 'SENSORS' -and $h -match 'SENSORS' -and $null -ne $j.Details.Sensors) 'sensor formats' }
Test-Case 'Zero sensor value is preserved' { $s=Get-SensorSnapshot { New-SensorRecord 'CPU' 'Power' 0 'W' 'Fixture' (Get-Date) }; Assert-Equal $s.Sensors[0].Value 0 'zero value' }
Test-Case 'LHM manifests pin official assets' { $a=Get-Content (Join-Path $PSScriptRoot '..\runtimes\windows-x64\powershell51\manifest.json') -Raw | ConvertFrom-Json; $b=Get-Content (Join-Path $PSScriptRoot '..\runtimes\windows-x64\powershell7\manifest.json') -Raw | ConvertFrom-Json; Assert-Equal $a.version '0.9.6' 'ps5 version'; Assert-Equal $b.version '0.9.6' 'ps7 version'; Assert-True ($a.assetSha256.Length -eq 64 -and $b.assetSha256.Length -eq 64) 'manifest hashes' }
Test-Case 'LHM helper contract fixture is structured' { $x=[pscustomobject]@{schemaVersion='1.0';provider='LibreHardwareMonitor';runtime='PowerShell7-net10';status='PASS';hardware=@();sensors=@([pscustomobject]@{name='CPU Total';hardwareName='CPU';hardwareType='Cpu';sensorType='Load';value=0;unit='%';identifier='/cpu/load/0'});errors=@()}; Assert-True ($x.schemaVersion -and $x.provider -and $x.runtime -and $null -ne $x.sensors[0].value) 'contract fields' }
Write-Host "`nPassed: $passed  Failed: $failed"
if ($failed -gt 0) { exit 1 }
